#include <algorithm>

int main() {
  int arr[] = {1, 2, 4, 8, 16};

  int n = sizeof(arr) / sizeof(arr[0]);
  int min = *std::min_element(arr, arr + n); 
  int max = *std::max_element(arr, arr + n); 

  std::cout << "Minimum: " << min << "\n";
  std::cout << "Maximum: " << max << "\n";

  return 0;
}
